mapper.select:
SELECT s.scenario_no, s.category_no, c.name AS category_name, s.title, s.description, s.status, s.sort_order, s.active_version_no, s.frst_reg_dt, s.lst_chg_dt FROM tb_scenario s JOIN tb_scenario_category c ON c.scenario_category_no = s.category_no WHERE s.status != 'DELETED'
AND s.status = #{status}
ORDER BY s.scenario_no DESC
